use sqlx::{Connection, Row};
let value = tokio::runtime::Builder::new_current_thread().enable_all().build()?.block_on(async {
    let url = std::env::var("DATABASE_URL")?;
    let mut connection = sqlx::PgConnection::connect(&url).await?;
    let row = sqlx::query("SELECT 1.2300::numeric AS amount").fetch_one(&mut connection).await?;
    let value = <Decimal as sqlx::Decode<'_, sqlx::Postgres>>::decode(row.try_get_raw("amount")?)?;
    connection.close().await?;
    Ok::<Decimal, Box<dyn std::error::Error + Send + Sync>>(value)
})?;
